import logging
from robot.output.logger import LOGGER
from robot.output.pyloggingconf import RobotHandler
from robot.output.loggerhelper import Message


def add_robot_redirecting_handler(logger_name):
    """
    Add new RobotRedirectingHandler to given logger.

    :param logger_name: name of logger to which handler is added
    :return: None
    """
    logger = logging.getLogger(logger_name)
    for handler in logger.handlers:
        if isinstance(handler, RobotRedirectingHandler):
            break
    else:
        handler = RobotRedirectingHandler()
        logger.addHandler(handler)


class RobotRedirectingHandler(RobotHandler):
    """
    Handler for redirecting log-records from python logging module to
    RobotFramework logger.

    Can be used only in the following situations:
    - logging from python slave threads
    - logging from logger with propagate setting set to False.

    In other cases logs will be duplicated because RobotFramework
    registers RobotHandler during initialization. That RobotHandler
    also redirects log-records into Robot-native logging system but
    does it only:
    - from logging root logger
    - from python main thread (and 'RobotFrameworkTimeoutThread').
    """

    def emit(self, record):
        """
        Send a log record to Robot-native logger system with
        python logging level translated to Robot logging level.

        :param record:
        :return:
        """
        message, error = self._get_message(record)
        level = self._get_robot_logger_level(record.levelno)
        LOGGER.log_message(Message(message, level))
        if error:
            LOGGER.log_message(Message(error, 'DEBUG'))

    def _get_robot_logger_level(self, level):
        if level >= logging.ERROR:
            return 'ERROR'
        if level >= logging.WARNING:
            return 'WARN'
        if level >= logging.INFO:
            return 'INFO'
        if level >= logging.DEBUG:
            return 'DEBUG'
        return 'TRACE'
